package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The rates for each grade, kept per sheet, each applying from its from-date. A rate with no
 *  from-date applies from the beginning of time (stored as {@link #START}). A grade with no rate is
 *  absent. */
@Repository
public class RateStore {

    /** The stored from-date of a rate that applies from the beginning of time. */
    private static final LocalDate START = LocalDate.of(1, 1, 1);

    private final JdbcTemplate jdbc;

    public RateStore(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Every rate on the sheet, by grade then from-date. */
    public List<RateResponse> list(String sheetId) {
        return jdbc.query("SELECT grade, pct, from_date FROM rate WHERE sheet_id = ? ORDER BY grade, from_date",
                (rs, i) -> {
                    LocalDate from = rs.getObject("from_date", LocalDate.class);
                    return RateResponse.of(rs.getString("grade"), rs.getBigDecimal("pct"),
                            START.equals(from) ? null : from);
                }, sheetId);
    }

    /** The grade's percent in force on the date (the rate with the latest from-date on or before it),
     *  or null when no rate of the grade applies then. */
    public BigDecimal find(String sheetId, String grade, LocalDate on) {
        List<BigDecimal> found = jdbc.queryForList(
                "SELECT pct FROM rate WHERE sheet_id = ? AND grade = ? AND from_date <= ? ORDER BY from_date DESC LIMIT 1",
                BigDecimal.class, sheetId, grade, on);
        return found.isEmpty() ? null : found.get(0);
    }

    /** Sets the grade's rate from the date (null for from the beginning of time), replacing any there. */
    public void set(String sheetId, String grade, LocalDate from, BigDecimal pct) {
        jdbc.update("MERGE INTO rate (sheet_id, grade, from_date, pct) KEY (sheet_id, grade, from_date) VALUES (?, ?, ?, ?)",
                sheetId, grade, from == null ? START : from, pct);
    }
}
package net.officefloor.hq.app.person;

import java.sql.PreparedStatement;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** The people kept per sheet, in the order they were added. */
@Repository
public class PersonStore {

    private static final RowMapper<Person> ROW = (rs, i) -> new Person(rs.getLong("id"),
            rs.getString("sheet_id"), rs.getString("name"), rs.getString("grade"), rs.getLong("version"));

    private final JdbcTemplate jdbc;

    public PersonStore(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public List<Person> list(String sheetId) {
        return jdbc.query("SELECT * FROM person WHERE sheet_id = ? ORDER BY id", ROW, sheetId);
    }

    public Person find(String sheetId, long id) {
        List<Person> found = jdbc.query("SELECT * FROM person WHERE sheet_id = ? AND id = ?", ROW, sheetId, id);
        return found.isEmpty() ? null : found.get(0);
    }

    /** Whether another person on the sheet (not {@code exceptId}) has this name, ignoring case. */
    public boolean nameTaken(String sheetId, String name, Long exceptId) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND name_key = LOWER(?) AND id <> ?",
                Integer.class, sheetId, name.trim(), exceptId == null ? -1L : exceptId);
        return n != null && n > 0;
    }

    public Person add(String sheetId, String name, String grade) {
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO person (sheet_id, name, grade) VALUES (?, ?, ?)", new String[] { "ID" });
            ps.setString(1, sheetId);
            ps.setString(2, name);
            ps.setString(3, grade);
            return ps;
        }, keys);
        return new Person(keys.getKey().longValue(), sheetId, name, grade, 0);
    }

    /**
     * Stores the person over the version it was loaded at, moving the version on; false (nothing
     * stored) when someone else has stored another version since.
     */
    public boolean save(Person person) {
        int n = jdbc.update(
                "UPDATE person SET name = ?, grade = ?, version = version + 1 WHERE sheet_id = ? AND id = ? AND version = ?",
                person.getName(), person.getGrade(), person.getSheetId(), person.getId(), person.getVersion());
        if (n == 1) {
            person.setVersion(person.getVersion() + 1);
        }
        return n == 1;
    }
}
package net.officefloor.hq.app.person;

/** A person on a sheet. {@code grade} is one of A, B or C; {@code version} moves on with each stored edit. */
public class Person {
    private final long id;
    private final String sheetId;
    private String name;
    private String grade;
    private long version;

    public Person(long id, String sheetId, String name, String grade, long version) {
        this.id = id;
        this.sheetId = sheetId;
        this.name = name;
        this.grade = grade;
        this.version = version;
    }

    public long getId() { return id; }
    public String getSheetId() { return sheetId; }
    public String getName() { return name; }
    public String getGrade() { return grade; }
    public long getVersion() { return version; }
    public void setName(String name) { this.name = name; }
    public void setGrade(String grade) { this.grade = grade; }
    public void setVersion(long version) { this.version = version; }
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/**
 * The per-sheet settings. {@link #today(String)} is the date every date-dependent decision and
 * default in the app uses — never the real clock.
 */
@Repository
public class SheetStore {

    private final JdbcTemplate jdbc;

    public SheetStore(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's today: as set on the sheet, else the real date. */
    public LocalDate today(String sheetId) {
        List<LocalDate> found = jdbc.query("SELECT today FROM sheet WHERE id = ?",
                (rs, i) -> rs.getObject(1, LocalDate.class), sheetId);
        return found.isEmpty() ? LocalDate.now() : found.get(0);
    }

    public void setToday(String sheetId, LocalDate today) {
        jdbc.update("MERGE INTO sheet (id, today) KEY (id) VALUES (?, ?)", sheetId, today);
    }
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

public class SaveToday {
    public void save(@PathVariable("sheetId") String sheetId, @Val LocalDate today, SheetStore store) {
        store.setToday(sheetId.trim(), today);
    }
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateToday {
    public void validate(@RequestBody TodayRequest request, Out<LocalDate> today) throws InvalidSheetException {
        String text = request == null || request.today() == null ? "" : request.today().trim();
        try {
            today.set(LocalDate.parse(text));
        } catch (DateTimeParseException e) {
            throw new InvalidSheetException("Not a date: " + text);
        }
    }
}
